const LangContext = React.createContext({ lang: 'zh', t: (k) => k, setLang: () => {} });

function makeT(lang) {
  return (key, ...args) => {
    const dict = I18N[lang] || I18N.zh;
    const v = dict[key];
    if (v === undefined) {
      const fb = I18N.zh[key];
      if (typeof fb === 'function') return fb(...args);
      return fb === undefined ? key : fb;
    }
    if (typeof v === 'function') return v(...args);
    return v;
  };
}

function LangProvider({ children }) {
  const [lang, setLangState] = React.useState(() => {
    try { return localStorage.getItem('ocip-lang') || 'zh'; } catch { return 'zh'; }
  });
  const setLang = React.useCallback((l) => {
    setLangState(l);
    try { localStorage.setItem('ocip-lang', l); } catch {}
  }, []);
  const t = React.useMemo(() => makeT(lang), [lang]);
  const value = React.useMemo(() => ({ lang, setLang, t }), [lang, setLang, t]);
  return React.createElement(LangContext.Provider, { value }, children);
}

function useT() {
  return React.useContext(LangContext);
}

// Global tr — reads current lang from localStorage so it works outside React context
// (modal/open helpers, module-level constants). Components should prefer useT() for reactivity.
function globalTr(key) {
  let lang = 'zh';
  try { lang = localStorage.getItem('ocip-lang') || 'zh'; } catch {}
  const dict = I18N[lang] || I18N.zh;
  const v = dict[key];
  if (v === undefined) {
    const fb = I18N.zh[key];
    return fb === undefined ? key : fb;
  }
  return v;
}

// Region name helper (used everywhere)
function regionName(code, lang) {
  const r = REGION_MAP[code];
  if (!r) return code;
  return lang === 'en' ? r.en : getRegionSimpleName(r);
}

Object.assign(window, { I18N, LangContext, LangProvider, useT, makeT, regionName, tr: globalTr });
